package de.openspri.soap

import jakarta.xml.bind.JAXBContext
import jakarta.xml.bind.JAXBElement
import org.w3c.dom.Element
import javax.xml.transform.dom.DOMResult

/** JAXB context for all S/PRI schema packages (generated by module spri-schema). */
object SpriJaxb {

    private const val BASE = "de.telekom.spri.oss.v4"

    val context: JAXBContext = JAXBContext.newInstance(
        listOf("envelope", "order", "message", "complex", "fttx", "enm", "simple").joinToString(":") { "$BASE.$it" },
        SpriJaxb::class.java.classLoader,
    )

    fun <T> unmarshal(element: Element, type: Class<T>): T =
        context.createUnmarshaller().unmarshal(element, type).value

    /** Marshals a JAXB element into a standalone DOM element. */
    fun marshal(value: JAXBElement<*>): Element {
        val result = DOMResult(SecureXml.newDocument())
        context.createMarshaller().marshal(value, result)
        return (result.node as org.w3c.dom.Document).documentElement
    }
}
